/* Arte do guardião: quadros da folha de sprites enviada pelo autor (fundo removido, ruído do JPG reduzido). Gerado, não editar à mão. */
const ARTE_BOSS={"peq": {"w": 40, "h": 41, "f": ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"]}, "bol": {"w": 108, "h": 57, "f": ["data:image/png;base64,", "data:image/png;base64,"]}, "big": {"w": 121, "h": 98, "f": ["data:image/png;base64,", "data:image/png;base64,"]}, "fraco": {"w": 122, "h": 88, "f": ["data:image/png;base64,"]}};
(function(){for(const k in ARTE_BOSS){const o=ARTE_BOSS[k];o.img=o.f.map(s=>{const i=new Image();i.src=s;return i;});}})();
function bossArte(k,i){const o=ARTE_BOSS[k],m=o.img[i%o.img.length];return m&&m.complete&&m.naturalWidth?m:null;}
